[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create &amp; Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,400&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --purple-light: #9B6BFF;
      --purple-faint: #f3eeff;
      --orange: #FF7A00;
      --orange-light: #FF9A40;
      --orange-faint: #fff4eb;
      --white: #ffffff;
      --gray-50: #f9f9fb;
      --gray-100: #f2f2f5;
      --gray-200: #e5e5ea;
      --gray-400: #a0a0b0;
      --gray-600: #6e6e82;
      --gray-800: #1c1c2e;
      --radius-sm: 8px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --radius-xl: 32px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
      background: var(--white);
      color: var(--gray-800);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }
    img { display: block; max-width: 100%; }

    /* ─── HEADER ─────────────────────────────────────────── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--gray-200);
    }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 68px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.25rem;
      color: var(--black);
      letter-spacing: -0.02em;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 20px; height: 20px; fill: white; }

    .header-right {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-login {
      padding: 8px 22px;
      border-radius: 100px;
      font-weight: 700;
      font-size: 0.9rem;
      background: var(--black);
      color: var(--white);
      transition: opacity 0.15s;
    }
    .btn-login:hover { opacity: 0.8; }

    /* hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
      border-radius: 8px;
      transition: background 0.15s;
    }
    .hamburger:hover { background: var(--gray-100); }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: transform 0.25s, opacity 0.25s;
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* mobile nav overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      inset: 68px 0 0 0;
      background: var(--white);
      z-index: 99;
      padding: 32px 24px;
      flex-direction: column;
      gap: 8px;
      overflow-y: auto;
      border-top: 1px solid var(--gray-200);
      animation: slideDown 0.2s ease;
    }
    .mobile-nav.open { display: flex; }

    @keyframes slideDown {
      from { opacity: 0; transform: translateY(-8px); }
      to   { opacity: 1; transform: translateY(0); }
    }

    .mobile-nav a {
      font-size: 1.1rem;
      font-weight: 600;
      padding: 14px 0;
      border-bottom: 1px solid var(--gray-100);
      color: var(--gray-800);
      transition: color 0.15s;
    }
    .mobile-nav a:hover { color: var(--purple); }

    .mobile-nav .btn-login-mobile {
      margin-top: 16px;
      padding: 14px;
      border-radius: 100px;
      background: var(--black);
      color: var(--white);
      font-weight: 700;
      font-size: 1rem;
      text-align: center;
    }

    /* ─── HERO ───────────────────────────────────────────── */
    .hero {
      position: relative;
      min-height: 90vh;
      display: flex;
      align-items: center;
      overflow: hidden;
      background: var(--white);
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      z-index: 0;
      overflow: hidden;
    }

    /* Abstract gradient blobs */
    .hero-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(80px);
      opacity: 0.35;
    }
    .hero-blob-1 {
      width: 600px; height: 600px;
      background: radial-gradient(circle, #9B6BFF, transparent);
      top: -100px; right: -80px;
    }
    .hero-blob-2 {
      width: 480px; height: 480px;
      background: radial-gradient(circle, #FF9A40, transparent);
      bottom: -60px; left: -60px;
    }
    .hero-blob-3 {
      width: 300px; height: 300px;
      background: radial-gradient(circle, #FF7A00, transparent);
      top: 40%; right: 30%;
      opacity: 0.2;
    }

    /* Grid dot pattern */
    .hero-grid {
      position: absolute;
      inset: 0;
      background-image: radial-gradient(circle, rgba(118,56,250,0.12) 1px, transparent 1px);
      background-size: 40px 40px;
      z-index: 0;
    }

    .hero-inner {
      position: relative;
      z-index: 1;
      max-width: 1200px;
      margin: 0 auto;
      padding: 80px 24px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .hero-content {}

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 6px 14px;
      border-radius: 100px;
      background: var(--purple-faint);
      color: var(--purple);
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      margin-bottom: 28px;
    }
    .hero-badge::before {
      content: '';
      width: 6px; height: 6px;
      border-radius: 50%;
      background: var(--purple);
    }

    .hero-title {
      font-size: clamp(2.6rem, 5.5vw, 4.2rem);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.03em;
      color: var(--black);
      margin-bottom: 28px;
    }

    .hero-title .accent-purple { color: var(--purple); }
    .hero-title .accent-orange { color: var(--orange); }

    .hero-sub {
      font-size: 1.15rem;
      color: var(--gray-600);
      max-width: 480px;
      margin-bottom: 40px;
      line-height: 1.7;
    }

    .btn-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 16px 36px;
      border-radius: 100px;
      font-weight: 800;
      font-size: 1rem;
      background: linear-gradient(135deg, var(--purple), #a855f7);
      color: var(--white);
      box-shadow: 0 8px 32px rgba(118,56,250,0.35);
      transition: transform 0.15s, box-shadow 0.15s;
      letter-spacing: -0.01em;
    }
    .btn-cta:hover {
      transform: translateY(-2px);
      box-shadow: 0 12px 40px rgba(118,56,250,0.45);
    }
    .btn-cta:active { transform: translateY(0); }

    .hero-visual {
      display: flex;
      justify-content: center;
      align-items: center;
    }

    /* Phone mockup cluster */
    .phone-cluster {
      position: relative;
      width: 340px;
      height: 480px;
    }

    .phone-card {
      position: absolute;
      border-radius: 24px;
      overflow: hidden;
      box-shadow: 0 24px 60px rgba(0,0,0,0.18);
    }

    .phone-card-main {
      width: 200px;
      height: 360px;
      left: 50%;
      top: 50%;
      transform: translate(-50%, -50%);
      background: linear-gradient(160deg, #7638FA 0%, #FF7A00 100%);
      z-index: 3;
      display: flex;
      flex-direction: column;
      padding: 20px;
    }

    .phone-card-left {
      width: 160px;
      height: 280px;
      left: -10px;
      top: 50%;
      transform: translateY(-50%) rotate(-8deg);
      background: linear-gradient(160deg, #1c1c2e 0%, #3a2060 100%);
      z-index: 2;
    }

    .phone-card-right {
      width: 160px;
      height: 280px;
      right: -10px;
      top: 50%;
      transform: translateY(-50%) rotate(8deg);
      background: linear-gradient(160deg, #FF7A00 0%, #FFD166 100%);
      z-index: 2;
    }

    .phone-notch {
      width: 60px;
      height: 8px;
      background: rgba(255,255,255,0.2);
      border-radius: 4px;
      margin: 0 auto 20px;
    }

    .phone-img-placeholder {
      flex: 1;
      border-radius: 14px;
      background: rgba(255,255,255,0.15);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .phone-img-placeholder svg {
      width: 48px;
      height: 48px;
      fill: rgba(255,255,255,0.7);
    }

    .phone-stat {
      margin-top: 12px;
      background: rgba(255,255,255,0.2);
      border-radius: 10px;
      padding: 8px 12px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .phone-stat-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      background: var(--orange-light);
    }

    .phone-stat-text {
      font-size: 0.72rem;
      color: rgba(255,255,255,0.9);
      font-weight: 600;
    }

    /* Floating badges */
    .float-badge {
      position: absolute;
      background: var(--white);
      border-radius: 14px;
      padding: 10px 14px;
      box-shadow: 0 8px 30px rgba(0,0,0,0.12);
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 0.78rem;
      font-weight: 700;
      color: var(--gray-800);
      z-index: 10;
    }

    .float-badge-1 {
      top: 20px;
      left: -20px;
    }

    .float-badge-2 {
      bottom: 30px;
      right: -20px;
    }

    .float-badge .badge-icon {
      width: 28px; height: 28px;
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1rem;
    }

    .float-badge-1 .badge-icon { background: var(--purple-faint); }
    .float-badge-2 .badge-icon { background: var(--orange-faint); }

    /* ─── SECTION COMMONS ────────────────────────────────── */
    .section {
      padding: 96px 0;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .section-label {
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(1.8rem, 3.5vw, 2.8rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.025em;
      margin-bottom: 20px;
    }

    .section-desc {
      font-size: 1.05rem;
      color: var(--gray-600);
      max-width: 560px;
      line-height: 1.75;
      margin-bottom: 32px;
    }

    .link-arrow {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-weight: 700;
      font-size: 0.95rem;
      transition: gap 0.15s;
    }
    .link-arrow:hover { gap: 8px; }

    /* ─── FEATURES ───────────────────────────────────────── */
    .features {
      background: var(--gray-50);
    }

    .features-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .features-label { color: var(--purple); }
    .features-title { color: var(--black); }
    .features-link { color: var(--purple); }

    .features-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .feature-pill {
      background: var(--white);
      border: 1.5px solid var(--gray-200);
      border-radius: var(--radius-md);
      padding: 20px;
      transition: border-color 0.15s, box-shadow 0.15s, transform 0.15s;
    }

    .feature-pill:hover {
      border-color: var(--purple);
      box-shadow: 0 4px 20px rgba(118,56,250,0.12);
      transform: translateY(-2px);
    }

    .feature-pill-icon {
      width: 44px; height: 44px;
      border-radius: 12px;
      margin-bottom: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
    }

    .feature-pill-name {
      font-weight: 700;
      font-size: 0.95rem;
      color: var(--black);
      margin-bottom: 4px;
    }

    .feature-pill-desc {
      font-size: 0.82rem;
      color: var(--gray-600);
      line-height: 1.5;
    }

    /* ─── SAFETY ─────────────────────────────────────────── */
    .safety {
      background: var(--white);
    }

    .safety-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .safety-label { color: #22c55e; }
    .safety-link { color: #16a34a; }

    .safety-visual {
      position: relative;
    }

    .safety-card-wrap {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      background: linear-gradient(135deg, #f0fdf4, #dcfce7, #bbf7d0);
      padding: 40px;
      min-height: 360px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .safety-shield {
      width: 72px; height: 72px;
      border-radius: 20px;
      background: #22c55e;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 8px;
    }

    .safety-shield svg {
      width: 36px; height: 36px;
      fill: white;
    }

    .safety-feature-chip {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: white;
      border-radius: 100px;
      padding: 10px 16px;
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--gray-800);
      box-shadow: 0 2px 12px rgba(0,0,0,0.07);
    }

    .safety-feature-chip .chip-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      background: #22c55e;
    }

    /* ─── CREATORS ───────────────────────────────────────── */
    .creators {
      background: var(--black);
      position: relative;
      overflow: hidden;
    }

    .creators-bg-blob-1 {
      position: absolute;
      width: 500px; height: 500px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(118,56,250,0.3), transparent);
      top: -100px; right: -100px;
      filter: blur(60px);
      pointer-events: none;
    }

    .creators-bg-blob-2 {
      position: absolute;
      width: 400px; height: 400px;
      border-radius: 50%;
      background: radial-gradient(circle, rgba(255,122,0,0.25), transparent);
      bottom: -80px; left: -60px;
      filter: blur(60px);
      pointer-events: none;
    }

    .creators-inner {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
