    .creators-label { color: var(--orange); }
    .creators-title { color: var(--white); }
    .creators-desc { color: rgba(255,255,255,0.65); }
    .creators-link { color: var(--orange); }

    .creators-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }

    .creator-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      aspect-ratio: 4/5;
      position: relative;
    }

    .creator-card-bg {
      position: absolute;
      inset: 0;
    }

    .creator-card:nth-child(1) .creator-card-bg {
      background: linear-gradient(160deg, #7638FA 0%, #c084fc 100%);
    }
    .creator-card:nth-child(2) .creator-card-bg {
      background: linear-gradient(160deg, #FF7A00 0%, #FFD166 100%);
      margin-top: 28px;
    }
    .creator-card:nth-child(3) .creator-card-bg {
      background: linear-gradient(160deg, #1c1c2e 0%, #7638FA 100%);
    }
    .creator-card:nth-child(4) .creator-card-bg {
      background: linear-gradient(160deg, #FF7A00 0%, #ff4d4d 100%);
      margin-top: -28px;
    }

    .creator-card-inner {
      position: absolute;
      inset: 0;
      padding: 16px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
    }

    .creator-avatar {
      width: 36px; height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.3);
      border: 2px solid rgba(255,255,255,0.5);
      margin-bottom: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1rem;
    }

    .creator-stat {
      font-size: 0.72rem;
      color: rgba(255,255,255,0.85);
      font-weight: 600;
      background: rgba(0,0,0,0.25);
      padding: 4px 8px;
      border-radius: 6px;
      display: inline-block;
    }

    .creator-icon-center {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      font-size: 2.5rem;
      opacity: 0.5;
    }

    /* ─── TAGLINE BANNER ─────────────────────────────────── */
    .tagline-banner {
      background: linear-gradient(135deg, var(--purple) 0%, var(--orange) 100%);
      padding: 72px 24px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .tagline-banner::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.06'%3E%3Ccircle cx='30' cy='30' r='1'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }

    .tagline-text {
      position: relative;
      font-size: clamp(2rem, 4.5vw, 3.6rem);
      font-weight: 800;
      color: var(--white);
      letter-spacing: -0.025em;
      line-height: 1.15;
      max-width: 700px;
      margin: 0 auto;
    }

    /* ─── NEWS ───────────────────────────────────────────── */
    .news {
      background: var(--white);
      padding-bottom: 80px;
    }

    .news-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 40px;
      gap: 24px;
    }

    .news-header-left {}

    .news-label { color: var(--purple); }
    .news-title { color: var(--black); margin-bottom: 0; }

    .news-view-more {
      flex-shrink: 0;
      font-weight: 700;
      font-size: 0.9rem;
      color: var(--purple);
      border: 2px solid var(--purple);
      border-radius: 100px;
      padding: 8px 20px;
      transition: background 0.15s, color 0.15s;
      white-space: nowrap;
    }
    .news-view-more:hover {
      background: var(--purple);
      color: var(--white);
    }

    /* Carousel */
    .carousel-wrapper {
      position: relative;
    }

    .carousel {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding: 8px 4px 20px;
      scrollbar-width: none;
    }
    .carousel::-webkit-scrollbar { display: none; }

    .news-card {
      flex: 0 0 300px;
      scroll-snap-align: start;
      border-radius: var(--radius-lg);
      background: var(--white);
      border: 1.5px solid var(--gray-200);
      overflow: hidden;
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0,0,0,0.10);
    }

    .news-thumbnail {
      width: 100%;
      aspect-ratio: 16/9;
      position: relative;
      overflow: hidden;
    }

    .news-thumb-bg {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .news-card:nth-child(1) .news-thumb-bg {
      background: linear-gradient(135deg, #7638FA, #c084fc);
    }
    .news-card:nth-child(2) .news-thumb-bg {
      background: linear-gradient(135deg, #FF7A00, #FFD166);
    }
    .news-card:nth-child(3) .news-thumb-bg {
      background: linear-gradient(135deg, #1c1c2e, #7638FA);
    }
    .news-card:nth-child(4) .news-thumb-bg {
      background: linear-gradient(135deg, #16a34a, #4ade80);
    }

    .news-thumb-icon {
      font-size: 2.5rem;
      opacity: 0.6;
    }

    .news-card-body {
      padding: 20px;
    }

    .news-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 12px;
    }

    .news-tag {
      font-size: 0.68rem;
      font-weight: 700;
      letter-spacing: 0.06em;
      color: var(--purple);
      background: var(--purple-faint);
      border-radius: 100px;
      padding: 3px 10px;
    }

    .news-tag.tag-orange {
      color: var(--orange);
      background: var(--orange-faint);
    }

    .news-tag.tag-green {
      color: #16a34a;
      background: #f0fdf4;
    }

    .news-card-title {
      font-size: 0.95rem;
      font-weight: 700;
      color: var(--black);
      line-height: 1.45;
      margin-bottom: 12px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-card-date {
      font-size: 0.78rem;
      color: var(--gray-400);
      font-weight: 500;
    }

    /* Scroll arrows */
    .carousel-arrow {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 44px; height: 44px;
      border-radius: 50%;
      background: var(--white);
      border: 1.5px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 4px 16px rgba(0,0,0,0.1);
      cursor: pointer;
      z-index: 5;
      transition: background 0.15s, border-color 0.15s;
    }

    .carousel-arrow:hover {
      background: var(--black);
      border-color: var(--black);
    }

    .carousel-arrow:hover svg { stroke: white; }

    .carousel-arrow svg {
      width: 18px; height: 18px;
      stroke: var(--gray-800);
      fill: none;
      stroke-width: 2;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .arrow-prev { left: -22px; }
    .arrow-next { right: -22px; }

    /* ─── CTA DOWNLOAD ───────────────────────────────────── */
    .cta-download {
      background: var(--gray-50);
      padding: 96px 24px;
      text-align: center;
    }

    .cta-download-inner {
      max-width: 600px;
      margin: 0 auto;
    }

    .cta-download-headline {
      font-size: clamp(2rem, 4vw, 3.2rem);
      font-weight: 800;
      letter-spacing: -0.025em;
      color: var(--black);
      margin-bottom: 4px;
    }

    .cta-download-sub {
      font-size: clamp(1.8rem, 3.5vw, 2.8rem);
      font-weight: 800;
      letter-spacing: -0.025em;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 40px;
    }

    .store-buttons {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .store-btn {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 28px;
      border-radius: 14px;
      background: var(--black);
      color: var(--white);
      font-weight: 700;
      transition: transform 0.15s, box-shadow 0.15s;
    }

    .store-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(0,0,0,0.18);
    }

    .store-btn-icon {
      font-size: 1.6rem;
    }

    .store-btn-text {
      display: flex;
      flex-direction: column;
      text-align: left;
    }

    .store-btn-sub {
      font-size: 0.7rem;
      font-weight: 500;
      opacity: 0.7;
      letter-spacing: 0.02em;
    }

    .store-btn-name {
      font-size: 1rem;
      font-weight: 800;
    }

    /* ─── FOOTER ─────────────────────────────────────────── */
    footer {
      background: var(--black);
      padding: 64px 0 0;
    }

    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.1rem;
      color: var(--white);
      margin-bottom: 48px;
    }

    .footer-logo-icon {
      width: 32px; height: 32px;
      border-radius: 9px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .footer-logo-icon svg { width: 18px; height: 18px; fill: white; }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 32px;
      padding-bottom: 48px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }

    .footer-col-title {
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: rgba(255,255,255,0.45);
      margin-bottom: 16px;
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-col ul li a {
      font-size: 0.88rem;
      color: rgba(255,255,255,0.7);
      font-weight: 500;
      transition: color 0.15s;
    }

    .footer-col ul li a:hover {
      color: var(--white);
    }

    .footer-col ul li a .ext {
      color: rgba(255,255,255,0.35);
      font-size: 0.75em;
    }

    .footer-bottom {
      padding: 24px 0;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-bottom-left {
      display: flex;
      align-items: center;
      gap: 24px;
      flex-wrap: wrap;
    }

    .footer-lang-select {
      display: flex;
      align-items: center;
      gap: 6px;
      color: rgba(255,255,255,0.6);
      font-size: 0.82rem;
      font-weight: 500;
      background: rgba(255,255,255,0.08);
      border-radius: 8px;
      padding: 6px 12px;
      cursor: pointer;
      transition: background 0.15s;
    }

    .footer-lang-select:hover { background: rgba(255,255,255,0.14); }

    .footer-legal {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .footer-legal a {
      font-size: 0.78rem;
      color: rgba(255,255,255,0.45);
      font-weight: 500;
      transition: color 0.15s;
    }

    .footer-legal a:hover { color: rgba(255,255,255,0.8); }

    .footer-social {
      display: flex;
      gap: 10px;
      align-items: center;
    }

    .social-icon {
      width: 36px; height: 36px;
      border-radius: 10px;
      background: rgba(255,255,255,0.08);
      display: flex;
      align-items: center;
      justify-content: center;
      color: rgba(255,255,255,0.65);
      font-size: 0.85rem;
      font-weight: 700;
      transition: background 0.15s, color 0.15s;
      text-decoration: none;
    }

    .social-icon:hover {
      background: rgba(255,255,255,0.18);
      color: var(--white);
    }

    /* ─── RESPONSIVE ─────────────────────────────────────── */
    @media (max-width: 1024px) {
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 768px) {
      .hamburger { display: flex; }

      .header-right .btn-login { display: none; }

      .hero-inner {
        grid-template-columns: 1fr;
        gap: 48px;
        padding: 60px 24px;
        text-align: center;
      }

      .hero-sub { margin-left: auto; margin-right: auto; }
      .btn-cta { margin: 0 auto; }

      .hero-visual { display: none; }

      .features-inner,
      .safety-inner,
      .creators-inner {
        grid-template-columns: 1fr;
        gap: 40px;
      }

      .safety-visual,
      .creators-visual {
        order: -1;
      }

      .features-grid { grid-template-columns: 1fr 1fr; }

      .news-header {
        flex-direction: column;
        align-items: flex-start;
      }

      .news-card { flex: 0 0 260px; }

      .arrow-prev { left: -10px; }
      .arrow-next { right: -10px; }

      .footer-grid { grid-template-columns: repeat(2, 1fr); gap: 24px; }

      .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
      }

      .creators-visual { grid-template-columns: 1fr 1fr; }

      .section { padding: 64px 0; }
    }

    @media (max-width: 480px) {
      .features-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .store-buttons { flex-direction: column; align-items: center; }
    }
  </style>
</head>
